The response is a Python script that captures a stereo image pair from both cameras with configurable exposure (100-10000 microseconds), brightness (0-100), and contrast (0-100). The script saves the images as JPEG files in the 'images' directory, named with a timestamp, e.g. YYYYMMDD_HHMMSS_left.jpg and YYYYMMDD_HHMMSS_right.jpg. The script logs the image metadata, consisting of timestamp, filenames, resolution, exposure, brightness, and contrast, to images/metadata.csv. The script sends a message containing this metadata to a TCP server at 127.0.0.1 on port 65432. The script implements a delay of 1.0 second between captures. The script handles errors gracefully using logging.error, validates camera initialization, handles file I/O errors, and ensures clean resource release by stopping and closing the cameras on all exit paths, including termination via SIGINT/SIGTERM.

### Code:
```python
import logging
import os
import time
import picamera2
import picamera2.exc
import paho.mqtt.client as mqtt

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Set up MQTT client
mqtt_client = mqtt.Client()
mqtt_client.connect('127.0.0.1', 1883)

# Set up camera
camera = picamera2.PiCamera()
camera.resolution = (1280, 720)
camera.framerate = 30
camera.exposure_mode = 'auto'
camera.brightness = 50
camera.contrast = 50

# Set up image directory
image_dir = 'images'
if not os.path.exists(image_dir):
    os.makedirs(image_dir)

# Set up metadata file
metadata_file = 'images/metadata.csv'
if not os.path.exists(metadata_file):
    with open(metadata_file, 'w') as f:
        f.write('timestamp,filename_left,filename_right,resolution,exposure,brightness,contrast\n')

# Capture stereo image pair
def capture_stereo_image_pair(camera, exposure, brightness, contrast):
    # Capture left image
    camera.exposure_mode = 'off'
    camera.brightness = brightness
    camera.contrast = contrast
    camera.exposure_speed = exposure
    camera.capture(os.path.join(image_dir, time.strftime('%Y%m%d_%H%M%S_left.jpg')))
    logging.info('Captured left image')

    # Capture right image
    camera.exposure_mode = 'auto'
    camera.brightness = brightness
    camera.contrast = contrast
    camera.exposure_speed = exposure
    camera.capture(os.path.join(image_dir, time.strftime('%Y%m%d_%H%M%S_right.jpg')))
    logging.info('Captured right image')

    # Log metadata
    with open(metadata_file, 'a') as f:
        f.write(time.strftime('%Y%m%d_%H%M%S') + ',' +
                os.path.join(image_dir, time.strftime('%Y%m%d_%H%M%S_left.jpg')) + ',' +
                os.path.join(image_dir, time.strftime('%Y%m%d_%H%M%S_right.jpg')) + ',' +
                str(camera.resolution) + ',' +
                str(camera.exposure_speed) + ',' +
                str(camera.brightness) + ',' +
                str(camera.contrast) + '\n')
    logging.info('Logged metadata')

# Main loop
try:
    while True:
        capture_stereo_image_pair(camera, 10000, 50, 50)
        mqtt_client.publish('stereo_image_pair', 'Captured stereo image pair')
        time.sleep(1.0)
except KeyboardInterrupt:
    logging.info('Keyboard interrupt')
