import pigpio
import time

class OutputPin:
    def __init__(self, pin_number, initial_value):
        self.pin_number = pin_number
        self.initial_value = initial_value
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise Exception("pigpio daemon unreachable")
        if self.pin_number < 0 or self.pin_number > 31:
            raise Exception("pin_number out of range")
        if self.initial_value != 0 and self.initial_value != 1:
            raise Exception("initial_value must be 0 or 1")
        self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
        self.pi.write(self.pin_number, self.initial_value)

    def set_value(self, value):
        if value != 0 and value != 1:
            raise Exception("value must be 0 or 1")
        self.pi.write(self.pin_number, value)

    def shutdown(self):
        self.pi.set_mode(self.pin_number, pigpio.INPUT)
        self.pi.stop()

if __name__ == '__main__':
