        pin = OutputPin(17, 0)
        for i in range(5):
            pin.set_value(1)
            time.sleep(0.5)
            pin.set_value(0)
            time.sleep(0.5)
        pin.shutdown()
    except Exception as e:
        print(e)

import gpiozero
import time

class RotaryEncoder:
    def __init__(self, clk, dt, callback=None):
        self.clk = gpiozero.Button(clk, pull_up=True, bounce_time=0.005)
        self.dt = gpiozero.Button(dt, pull_up=True, bounce_time=0.005)
        self.callback = callback
        self.counter = 0
        self.clk.when_pressed = self.clk_pressed
        self.clk.when_released = self.clk_released
        self.dt.when_pressed = self.dt_pressed
        self.dt.when_released = self.dt_released

    def clk_pressed(self):
        if self.dt.is_pressed:
            self.counter += 1
        else:
            self.counter -= 1
        if self.callback:
            try:
                self.callback(self.counter)
            except:
                pass

    def clk_released(self):
        pass

    def dt_pressed(self):
        if self.clk.is_pressed:
            self.counter += 1
        else:
            self.counter -= 1
        if self.callback:
            try:
                self.callback(self.counter)
            except:
                pass

    def dt_released(self):
        pass

    def cleanup(self):
        self.clk.close()
        self.dt.close()

def callback(counter):
    print(counter)

if __name__ == '__main__':
    try:
        encoder = RotaryEncoder(17, 18, callback)
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        encoder.cleanup()

