import time
import board
import busio
import adafruit_servokit

from adafruit_servokit import ServoKit

i2c = busio.I2C(board.SCL, board.SDA)

kit = ServoKit(channels=16, i2c=i2c)

def grab_object(kit, servo_num=0):
    if servo_num < 0 or servo_num > 15:
        raise ValueError("Servo number must be 0-15")
    kit.servo[servo_num].angle = 90

def release_object(kit, servo_num=0):
    if servo_num < 0 or servo_num > 15:
        raise ValueError("Servo number must be 0-15")
    kit.servo[servo_num].angle = 150

def move_servo(kit, servo_num, target_angle):
    if servo_num < 0 or servo_num > 15:
        raise ValueError("Servo number must be 0-15")
    if target_angle < 0 or target_angle > 180:
        raise ValueError("Target angle must be 0-180 degrees")
    for angle in range(0, target_angle, 5):
        kit.servo[servo_num].angle = angle
        time.sleep(0.04)

try:
    grab_object(kit)
    release_object(kit)
    move_servo(kit, 0, 180)
except KeyboardInterrupt:
    pass
except OSError:
    print("I2C bus error")
except ValueError:
    print("Invalid servo number or target angle")
finally:
    kit.release()

import smbus2
import time

class I2CDevice:
    def __init__(self, address, bus_number=1):
        self.address = address
        self.bus = smbus2.SMBus(bus_number)
        self.bus.read_byte(self.address)

    def write_byte(self, register, value):
        self.bus.write_byte_data(self.address, register, value)

    def read_byte(self, register):
        return self.bus.read_byte_data(self.address, register)

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

