import smbus2
import time
import datetime

class DS1338:
    def __init__(self, bus=1, address=0x68):
        self.bus = smbus2.SMBus(bus)
        self.address = address
        self.seconds = 0
        self.minutes = 0
        self.hours = 0
        self.date = 0
        self.month = 0
        self.year = 0
        self.century = 21
        self.validate_century()
        self.validate_seconds()
        self.validate_minutes()
        self.validate_hours()
        self.validate_date()
        self.validate_month()
        self.validate_year()

    def validate_century(self):
        if self.century < 20:
            self.century = 20
        elif self.century > 29:
            self.century = 29

    def validate_seconds(self):
        if self.seconds < 0:
            self.seconds = 0
        elif self.seconds > 59:
            self.seconds = 59

    def validate_minutes(self):
        if self.minutes < 0:
            self.minutes = 0
        elif self.minutes > 59:
            self.minutes = 59

    def validate_hours(self):
        if self.hours < 0:
            self.hours = 0
        elif self.hours > 23:
            self.hours = 23

    def validate_date(self):
        if self.date < 1:
            self.date = 1
        elif self.date > 31:
            self.date = 31

    def validate_month(self):
        if self.month < 1:
            self.month = 1
        elif self.month > 12:
            self.month = 12

    def validate_year(self):
        if self.year < 0:
            self.year = 0
        elif self.year > 99:
            self.year = 99

    def read_datetime(self, century=21):
        self.century = century
        self.seconds = self.bus.read_byte_data(self.address, 0x00)
        self.minutes = self.bus.read_byte_data(self.address, 0x01)
        self.hours = self.bus.read_byte_data(self.address, 0x02)
        self.date = self.bus.read_byte_data(self.address, 0x04)
        self.month = self.bus.read_byte_data(self.address, 0x05)
        self.year = self.bus.read_byte_data(self.address, 0x06)
        self.validate_seconds()
        self.validate_minutes()
        self.validate_hours()
        self.validate_date()
        self.validate_month()
        self.validate_year()
        return datetime.datetime(self.century + self.year, self.month, self.date, self.hours, self.minutes, self.seconds)

    def write_all(self, seconds=None, minutes=None, hours=None, date=None, month=None, year=None):
        if seconds is not None:
            self.seconds = seconds
        if minutes is not None:
            self.minutes = minutes
        if hours is not None:
            self.hours = hours
        if date is not None:
            self.date = date
        if month is not None:
            self.month = month
        if year is not None:
            self.year = year
        self.validate_seconds()
        self.validate_minutes()
        self.validate_hours()
        self.validate_date()
        self.validate_month()
        self.validate_year()
        self.bus.write_byte_data(self.address, 0x00, self.seconds)
        self.bus.write_byte_data(self.address, 0x01, self.minutes)
        self.bus.write_byte_data(self.address, 0x02, self.hours)
        self.bus.write_byte_data(self.address, 0x04, self.date)
        self.bus.write_byte_data(self.address, 0x05, self.month)
        self.bus.write_byte_data(self.address, 0x06, self.year)

if __name__ == "__main__":
    rtc = DS1338()
    print(rtc.read_datetime())
    rtc.write_all(seconds=0, minutes=0, hours=0, date=1, month=1, year=0)
    print(rtc.read_datetime())

